capacities = {n: (1.0 + alpha) * bet_initial[n] for n in G.nodes()}

candidates = [68, 76, 64, 79, 37]
results = {}

def cascade_final_largest_component_size(trigger_node):
    # Start from intact graph and apply trigger
    H = G.copy()
    if H.has_node(trigger_node):
        H.remove_node(trigger_node)
    else:
        return 0
    # Iterate rounds
    while True:
        if len(H) == 0:
            return 0
        bet_H = nx.betweenness_centrality(H, normalized=False)
        to_fail = [n for n in bet_H if bet_H[n] > capacities.get(n, float('inf'))]
        if not to_fail:
            break
        H.remove_nodes_from(to_fail)
    if len(H) == 0:
        return 0
    # Size of the largest connected component after cascade
    largest = max(nx.connected_components(H), key=lambda c: len(c))
    return len(largest)

for c in candidates:
    size = cascade_final_largest_component_size(c)
    results[c] = size
    print(f"Candidate {c}: final largest CC size = {size}")

print("All candidate results:", results)
